ALTER TABLE users ADD COLUMN mobile_verified BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN notify_push BOOLEAN NOT NULL DEFAULT TRUE,
  ADD COLUMN notify_email BOOLEAN NOT NULL DEFAULT TRUE, ADD COLUMN delete_requested BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE refunds (id UUID PRIMARY KEY, order_id UUID NOT NULL UNIQUE REFERENCES payment_orders(id), user_id UUID NOT NULL REFERENCES users(id),
  reason VARCHAR(1000) NOT NULL, status VARCHAR(12) NOT NULL DEFAULT 'REQUESTED', admin_note VARCHAR(1000), reject_reason VARCHAR(1000),
  refund_txn_id VARCHAR(80), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id UUID PRIMARY KEY, actor_id UUID, action VARCHAR(80) NOT NULL, detail VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE device_tokens (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), token VARCHAR(400) NOT NULL UNIQUE,
  platform VARCHAR(10) NOT NULL DEFAULT 'android', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications (id UUID PRIMARY KEY, title VARCHAR(120) NOT NULL, message VARCHAR(500) NOT NULL, image_url VARCHAR(400), deep_link VARCHAR(300),
  audience VARCHAR(10) NOT NULL DEFAULT 'ALL', scheduled_at TIMESTAMPTZ, sent_at TIMESTAMPTZ, sent_count INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
